package com.aoo.bcg.spectator;

import com.fasterxml.jackson.databind.ObjectMapper;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;
import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;

class SpectatorServiceTest {
 private JdbcDataSource db;private MutableClock clock;private SpectatorService service;private final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 @BeforeEach void setup()throws Exception{db=new JdbcDataSource();db.setURL("jdbc:h2:mem:spectator;MODE=MySQL;DB_CLOSE_DELAY=-1");try(var c=db.getConnection();var s=c.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE aoo_hall_room(room_id BIGINT PRIMARY KEY,game_id BIGINT,classification_region_code VARCHAR,play_version VARCHAR,state VARCHAR,owner_account_id BIGINT)");s.execute("CREATE TABLE aoo_hall_room_member(room_id BIGINT,account_id BIGINT,status VARCHAR)");s.execute("CREATE TABLE aoo_room_event(room_id BIGINT,event_sequence BIGINT,event_type VARCHAR,event_payload VARCHAR,created_at TIMESTAMP,visibility VARCHAR,owner_player_id BIGINT)");s.execute("CREATE TABLE aoo_spectator_admission(request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id BIGINT,spectator_id BIGINT,status VARCHAR,requested_at TIMESTAMP,authorized_by BIGINT,authorized_at TIMESTAMP,left_at TIMESTAMP,row_version BIGINT)");s.execute("CREATE TABLE aoo_game_share(share_hash VARCHAR PRIMARY KEY,room_id BIGINT,created_by BIGINT,created_at TIMESTAMP,expires_at TIMESTAMP,revoked_at TIMESTAMP)");s.execute("INSERT INTO aoo_hall_room VALUES(10,7,'cn','v1','PLAYING',100)");s.execute("INSERT INTO aoo_hall_room_member VALUES(10,100,'JOINED')");}clock=new MutableClock(Instant.parse("2026-08-24T00:01:00Z"));var ports=new JdbcRoomReplayPorts(db,json);service=new SpectatorService(db,ports,ports,json,clock,Duration.ofSeconds(30));}
 @Test void closesAuthorizationDelayedReconnectCountAndExit()throws Exception{var pending=service.request(10,200);assertEquals("PENDING",pending.status());assertThrows(SecurityException.class,()->service.authorize(pending.requestId(),101,true));assertEquals("AUTHORIZED",service.authorize(pending.requestId(),100,true).status());try(var c=db.getConnection();var q=c.prepareStatement("INSERT INTO aoo_room_event VALUES(?,?,?,?,?,?,?)")){q.setLong(1,10);q.setLong(2,1);q.setString(3,"TURN");q.setString(4,"{\"seat\":1}");q.setTimestamp(5,java.sql.Timestamp.from(clock.instant().minusSeconds(31)));q.setString(6,"PUBLIC");q.setLong(7,0);q.executeUpdate();q.setLong(2,2);q.setString(4,"{\"seat\":2}");q.setTimestamp(5,java.sql.Timestamp.from(clock.instant().minusSeconds(5)));q.executeUpdate();q.setLong(2,3);q.setString(4,"{\"hand\":[1,2]}");q.setTimestamp(5,java.sql.Timestamp.from(clock.instant().minusSeconds(31)));q.setString(6,"PLAYER_PRIVATE");q.setLong(7,100);q.executeUpdate();}var reconnect=service.reconnect(10,200,0,10);var snapshot=(Map<?,?>)reconnect.get("snapshot");var incremental=(Map<?,?>)reconnect.get("incremental");assertEquals(1,((List<?>)incremental.get("events")).size());assertEquals("SPECTATOR_PUBLIC",snapshot.get("perspective"));assertEquals(1,((Map<?,?>)snapshot.get("summary")).get("spectatorCount"));assertEquals("LEFT",service.leave(10,200).status());assertThrows(SecurityException.class,()->service.stream(10,200,0,10));}
 @Test void rejectsForbiddenPublicPayloadAndShareIsOpaque()throws Exception{var p=service.request(10,200);service.authorize(p.requestId(),100,true);try(var c=db.getConnection();var s=c.createStatement()){s.execute("INSERT INTO aoo_room_event VALUES(10,1,'BAD','{\"internalState\":{}}',TIMESTAMP '2026-08-23 23:00:00','PUBLIC',0)");}assertThrows(SecurityException.class,()->service.stream(10,200,0,10));var share=service.share(10,100,Duration.ofMinutes(5));String token=(String)share.get("token");assertFalse(token.contains("10"));assertEquals(10L,service.shared(token).get("roomId"));clock.advance(Duration.ofMinutes(6));assertThrows(SecurityException.class,()->service.shared(token));}
 @Test void rejectsObfuscatedSecretKeys()throws Exception{var p=service.request(10,201);service.authorize(p.requestId(),100,true);try(var c=db.getConnection();var s=c.createStatement()){s.execute("INSERT INTO aoo_room_event VALUES(10,1,'BAD','{\"player_hand_cards\":[9]}',TIMESTAMP '2026-08-23 23:00:00','PUBLIC',0)");}assertThrows(SecurityException.class,()->service.snapshot(10,201,100));}
 static final class MutableClock extends Clock{private Instant now;MutableClock(Instant now){this.now=now;}void advance(Duration d){now=now.plus(d);}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now;}}
}
